 const published=data.publicationStatus==='published',downloadButton=$('#export'),publishButton=$('#publishBulletin'),state=$('#publicationState');
 const digitalButton=$('#downloadDigital');if(digitalButton)digitalButton.hidden=!published;if(downloadButton)downloadButton.hidden=true;if(publishButton){publishButton.hidden=published&&!!data.publishedBulletinId;publishButton.textContent=replacementPublication?'Publish replacement':'Publish bulletin';}const review=$('#viewPublished');if(review){review.hidden=!(published&&data.publishedBulletinId);review.href='published.html?id='+encodeURIComponent(data.publishedBulletinId);}if(state)state.textContent=published?'Published · '+dateText():'Draft · '+dateText();
