function splitHymn(value){
 const text=String(value||'').trim();
 const match=text.match(/^(?:Hymn\s*)?#?\s*(\d+)\s*(?:[·:—–-]\s*)?(.*)$/i);
 return match?{number:match[1],name:match[2]}:{number:'',name:text};
}
