 $('#editor').querySelectorAll('[data-program-toggle]').forEach(e=>e.onchange=()=>{
  const p=readProgramOptions(),key=e.dataset.programToggle,value=e.value==='true';
  if(key.startsWith('speaker-'))p.speakers[Number(key.slice(8))].show=value;else p[key]=value;
  syncProgram(p);save();
 });
 $('#editor').querySelectorAll('[data-speaker]').forEach(e=>e.oninput=()=>{
  const p=readProgramOptions();p.speakers[Number(e.dataset.speaker)][e.dataset.speakerPart]=e.value;syncProgram(p);save();
 });
