function normalizeWardNotes(w){if(Array.isArray(w.notesRows))return {...w,notesTitle:w.notesTitle??'NOTES'};const original=String(w.notes||''),rows=original.split('\n');if(/^\s*Class\s+Room\s*#/i.test(rows[0]||'')){const notesRows=rows.slice(1).filter(line=>line.trim()).map(line=>{const parts=line.trim().split(/\s{2,}|\s*\|\s*/);if(parts.length>1)return {className:parts.slice(0,-1).join(' '),room:parts.at(-1)};const match=line.trim().match(/^(.*?)\s+(\S+)$/);return {className:match?match[1]:line.trim(),room:match?match[2]:''};});return {...w,notesTitle:w.notesTitle??'NOTES',notesRows,notes:''};}return {...w,notesTitle:w.notesTitle??'NOTES',notesRows:[],notes:original};}
const typographySections=[['meeting','Meeting program'],['cover','Cover'],['leadership','Leadership'],['interviews','Interview instructions'],['missionaries','Missionaries'],['temple','Temple information'],['schedule','Meeting schedule'],['notes','Notes box'],['announcements','Announcements'],['contact','Bulletin contact'],['calendar','Calendar']];
function textAppearance(){try{return JSON.parse(data.textAppearance)||{}}catch{return {}}}
const bulletinFontList=[{id:'sans',label:'Helvetica',category:'Sans serif'},{id:'serif',label:'Times Roman',category:'Serif'},{id:'mono',label:'Courier',category:'Monospace'},...(window.BULLETIN_FONT_CATALOG||[])];
function bulletinFontOptions(defaultLabel,selected=''){return `<option value="" ${!selected?'selected':''}>${defaultLabel}</option>`+['Sans serif','Serif','Handwritten','Display','Monospace'].map(category=>`<optgroup label="${category}">${bulletinFontList.filter(font=>font.category===category).map(font=>`<option value="${font.id}" ${font.id===selected?'selected':''}>${font.label}</option>`).join('')}</optgroup>`).join('');}
function bulletinFontCss(family){return family==='sans'?'Arial, sans-serif':family==='serif'?'Times New Roman, serif':family==='mono'?'Courier New, monospace':bulletinFontList.some(font=>font.id===family)?`"${family}", serif`:'inherit';}
function typographyFields(section){const global=section==='global';return `<label class="field">Font family<select data-typography-section="${section}" data-typography-key="family">${bulletinFontOptions(global?'Original fonts':'Use bulletin default')}</select></label><p class="font-sample" data-font-sample-section="${section}">Aa Bb Cc - Your weekly bulletin - 123</p><label class="field">Base text size<select data-typography-section="${section}" data-typography-key="size">${(global?[]:[['','Use bulletin default']]).concat([[8,'8 pt'],[9,'9 pt'],[10,'10 pt (original scale)'],[11,'11 pt'],[12,'12 pt'],[14,'14 pt'],[16,'16 pt']]).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label class="field">Text style<select data-typography-section="${section}" data-typography-key="style">${[['',global?'Original styles':'Use bulletin default'],['normal','Regular'],['bold','Bold'],['italic','Italic'],['bolditalic','Bold italic']].map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><fieldset class="font-color-controls"><legend>Font color</legend><label class="field">Choose a color<input type="color" data-typography-section="${section}" data-typography-key="color" value="#141414" aria-label="${global?'Bulletin':section} font color"></label><label class="field">Color code<input type="text" data-typography-section="${section}" data-typography-key="color" value="#141414" pattern="#[0-9a-fA-F]{6}" maxlength="7" placeholder="#141414" spellcheck="false" aria-label="${global?'Bulletin':section} font color code"></label><div class="font-color-presets" role="group" aria-label="Preset font colors">${[['#141414','Black'],['#555555','Gray'],['#203f69','Navy'],['#25604f','Green'],['#65436b','Purple'],['#852d3e','Burgundy'],['#896319','Gold']].map(([color,label])=>`<button type="button" data-typography-color="${color}" data-typography-color-section="${section}" title="${label}" aria-label="${label} font color"><span style="background:${color}"></span>${label}</button>`).join('')}</div></fieldset>${global?'':`<button type="button" class="secondary" data-typography-reset="${section}">Use all bulletin defaults</button>`}`;}
function updateTextAppearanceControls(){const root=$('#textAppearanceSettings');if(!root)return;if(!root.dataset)root.dataset={};if(!root.dataset.initialized){root.innerHTML=`<details><summary style="padding:14px 0;font-weight:600;cursor:pointer">Text appearance</summary><p class="note">Choose bulletin-wide defaults or override a section. Headings scale proportionally. Large text may require shorter content; check the preview. Announcement-specific formatting remains available. Choose Color in the print settings to retain colored text. Black & white converts it to grayscale. Artwork containing lettering stays an image.</p><details><summary>Bulletin defaults</summary>${typographyFields('global')}</details>${typographySections.map(([key,label])=>`<details><summary style="padding:10px 0;font-weight:600">${label}</summary>${typographyFields(key)}</details>`).join('')}</details>`;root.dataset.initialized='yes';root.querySelectorAll('[data-typography-key]').forEach(input=>input.oninput=()=>{const config=textAppearance(),section=input.dataset.typographySection,key=input.dataset.typographyKey;if(key==='color'&&!/^#[0-9a-f]{6}$/i.test(input.value)){input.setCustomValidity?.('Enter a six-digit color code, such as #203f69.');return;}input.setCustomValidity?.('');config[section]={...config[section],[key]:input.value};data.textAppearance=JSON.stringify(config);save();});root.querySelectorAll('[data-typography-color]').forEach(button=>button.onclick=()=>{const config=textAppearance(),section=button.dataset.typographyColorSection;config[section]={...config[section],color:button.dataset.typographyColor};data.textAppearance=JSON.stringify(config);save();});root.querySelectorAll('[data-typography-reset]').forEach(button=>button.onclick=()=>{const config=textAppearance();delete config[button.dataset.typographyReset];data.textAppearance=JSON.stringify(config);save();});}const config=textAppearance();root.querySelectorAll('[data-typography-key]').forEach(input=>{if(document.activeElement===input)return;const section=input.dataset.typographySection,key=input.dataset.typographyKey;input.value=config[section]?.[key]??(key==='color'?(config.global?.color||'#141414'):key==='size'&&section==='global'?'10':'');if(key==='color'&&/^#[0-9a-f]{6}$/i.test(input.value))input.setCustomValidity?.('');});root.querySelectorAll('[data-font-sample-section]').forEach(sample=>{const selected=config[sample.dataset.fontSampleSection]||{},global=config.global||{},style=selected.style||global.style||'';sample.style.color=selected.color||global.color||'#141414';sample.style.fontFamily=bulletinFontCss(selected.family||global.family||'');sample.style.fontWeight=style.includes('bold')?'700':'400';sample.style.fontStyle=style.includes('italic')?'italic':'normal';});}
function readWard(){
 try{const w=JSON.parse(data.wardOptions);if(w&&Array.isArray(w.leadership)&&Array.isArray(w.missionaries)&&Array.isArray(w.schedule))return normalizeWardNotes(w);}catch{}
 const leadership=String(data.leadership||'').split('\n').filter(Boolean).map(line=>{const values=line.includes('|')?line.split('|'):line.split(/\s+[—–]\s+/);return {calling:(values[0]||'').trim(),name:(values[1]||'').trim(),phone:values.slice(2).join(' | ').trim()};});
 const missionaries=String(data.missionaries||'').split(/\n\s*\n/).filter(Boolean).map(block=>{const lines=block.split('\n').map(s=>s.trim()).filter(Boolean),name=lines.shift()||'',mission=/mission/i.test(lines[0]||'')?lines.shift():'',emailIndex=lines.findIndex(s=>s.includes('@')),email=emailIndex>=0?lines.splice(emailIndex,1)[0]:'';return {name,mission,address1:lines[0]||'',address2:lines[1]||'',address3:lines.slice(2).join(', '),email};});
 const parts=String(data.information||'').split(/\n\s*\n/),schedule=(parts.shift()||'').split('\n').filter(Boolean).map(line=>{const values=line.split(/[|·]/);return {className:(values.shift()||'').trim(),time:values.join(' | ').trim()};});
 return normalizeWardNotes({leadership,missionaries,schedule,notes:parts.join('\n\n').replace(/^Primary classes\s*\n?/i,'')});
}
function saveWard(w){
 data.wardOptions=JSON.stringify(w);
 data.leadership=w.leadership.filter(row=>row.calling||row.name||row.phone).map(row=>[row.calling,row.name,row.phone].join(' | ')).join('\n');
 data.missionaries=w.missionaries.map(row=>[row.name,row.mission,row.address1,row.address2,row.address3,row.email].filter(Boolean).join('\n')).filter(Boolean).join('\n\n');
 data.information=w.schedule.filter(row=>row.className||row.time).map(row=>[row.className,row.time].join(' | ')).join('\n')+(w.notes?'\n\n'+w.notes:'');save();
}
function wardInput(group,index,key,label,value,type='text'){
 return `<label class="field">${label}<input type="${type}" data-ward-group="${group}" data-ward-index="${index}" data-ward-key="${key}" value="${esc(value||'')}" aria-label="${label} ${index+1}"></label>`;
}
function wardSectionSettings(){try{return JSON.parse(data.wardSectionConfig)||{}}catch{return {}}}
function wardSection(key){const titles={leadership:'Ward / branch leadership',interviews:'',missionaries:'Missionaries',temple:'Temple information',information:meetingDate().getFullYear()+' Meeting Schedule',fifthSunday:''};return {title:titles[key]??'',mode:'structured',body:'',...(wardSectionSettings()[key]||{})};}
function wardSectionFields(field){const [key,label,type]=field,section=wardSection(key),structured=['leadership','missionaries','information'].includes(key);return `<label class="field">Section heading (optional)<input data-ward-section="${key}" data-ward-section-part="title" value="${esc(section.title)}" placeholder="Leave blank for no heading"></label>${structured?`<label class="field">Box layout<select data-ward-section="${key}" data-ward-section-part="mode"><option value="structured" ${section.mode!=='text'?'selected':''}>${key==='leadership'?'Leadership rows':key==='missionaries'?'Contact entries':'Schedule & notes'}</option><option value="text" ${section.mode==='text'?'selected':''}>General text</option></select></label><p class="note">Use General text to repurpose this box. Your original structured entries stay saved.</p>`:''}${structured&&section.mode==='text'?`<label class="field">Box information<textarea rows="8" data-ward-section="${key}" data-ward-section-part="body">${esc(section.body)}</textarea></label>`:meetingField(structured?field:[key,'Box information',type])}`;}
function bindWardSectionSettings(){$('#editor').querySelectorAll('[data-ward-section]').forEach(input=>input.oninput=()=>{const key=input.dataset.wardSection,part=input.dataset.wardSectionPart,config=wardSectionSettings();config[key]={...config[key],[part]:input.value};data.wardSectionConfig=JSON.stringify(config);if(part==='title'){const heading=$('#editor').querySelector('[data-ward-section-heading="'+key+'"]');if(heading)heading.textContent=input.value.trim()||groups['Ward / Branch'].find(field=>field[0]===key)[1];}save();if(part==='mode')edit();});}
