function meetingField([key,label,type]){
 if(key==='programTitle'){const defaultHeading=(programStyleChoices.find(style=>style[0]===data.programStyle)||programStyleChoices[0])[2];return `<label class="field">Program heading<input data-key="programTitle" type="text" value="${esc(data.programTitle||defaultHeading)}" placeholder="${esc(defaultHeading)}"></label><fieldset style="margin:12px 0;padding:12px;border:1px solid #b5cbce;border-radius:8px"><legend>Program heading visibility</legend>${[['true','Show heading'],['false','Hide heading completely']].map(([value,label])=>`<label style="display:flex;align-items:center;gap:8px;margin:8px 0"><input type="radio" style="width:auto;margin:0" name="programHeadingVisibility" data-key="showProgramHeading" value="${value}" ${(data.showProgramHeading!=='false')===(value==='true')?'checked':''}>${label}</label>`).join('')}</fieldset>${entryAlignmentFields('heading')}`;}
 if(type==='ward')return wardFields(key);
 if(type==='program')return programFields();
 if(type==='information')return programInformationFields();
 if(type==='hymn')return hymnFields(key,label);
 return `<label class="field">${label}${type==='textarea'?`<textarea data-key="${key}" rows="7">${esc(data[key])}</textarea>`:`<input data-key="${key}" type="${type||'text'}" value="${esc(data[key])}">`}</label>${['ward','date','presiding','conducting','welcomeNotes','wardStakeNotes','invocation','benediction'].includes(key)?entryAlignmentFields(({welcomeNotes:'welcome',wardStakeNotes:'wardItems'})[key]||key):''}`;
}
