function meetingSequence(includeHidden=false){
 const options=readProgramOptions(),items=[],add=(id,kind,label,value,show=true,extra={})=>items.push({id,kind,label,value:String(value||''),show:!!show,...extra});
 add('presiding','entry','Presiding',data.presiding);add('conducting','entry','Conducting',data.conducting);add('welcome','notes','Welcome and Announcements',data.welcomeNotes);
 add('opening','hymn','Opening Hymn',data.opening,hymnIsVisible('opening'),{extraLines:hymnExtraLines('opening'),lineAlignments:hymnLineAlignments('opening'),rightLabel:hymnRightText('opening')});add('invocation','entry','Invocation',data.invocation);add('wardItems','notes','Ward / Stake Items',data.wardStakeNotes);
 add('sacrament','hymn','Sacrament Hymn',data.sacrament,hymnIsVisible('sacrament'),{extraLines:hymnExtraLines('sacrament'),lineAlignments:hymnLineAlignments('sacrament'),rightLabel:hymnRightText('sacrament')});add('administration','center','Administration of the Sacrament','Administration of the Sacrament');add('fast','center','Fast and Testimony Meeting','Fast and Testimony Meeting',options.fast,{dots:true});
 const speakers=options.speakers.map((speaker,i)=>({...speaker,index:i})),visibleSpeakers=speakers.filter(s=>options.showSpeakers&&s.show&&s.name.trim()),extras=readExtraHymns();
 for(let position=0;position<=visibleSpeakers.length;position++){if(position){const speaker=visibleSpeakers[position-1];add('speaker-'+speaker.index,'entry',speaker.type||'Speaker',speaker.name,true);}for(const hymn of extras.filter(h=>Math.min(h.after,visibleSpeakers.length)===position))add('hymn-'+hymn.id,'hymn',hymn.label||'Hymn',hymn.number?'Hymn '+hymn.number+(hymn.name?' · '+hymn.name:''):hymn.name,hymn.show,{extraLines:hymn.extraLines||[],lineAlignments:hymn.lineAlignments||[],rightLabel:hymnRightText(hymn),id:'hymn-'+hymn.id});}
 for(const speaker of speakers.filter(s=>!visibleSpeakers.some(v=>v.index===s.index)))add('speaker-'+speaker.index,'entry',speaker.type||'Speaker',speaker.name,false);
 add('notes','notes','Other program information',options.notes,options.showNotes);for(const item of options.information||[])add('info-'+item.id,'notes',item.title||'Information',[(item.title||'').trim(),item.text].filter(Boolean).join('\n'),options.showNotes&&item.show);
 add('closing','hymn','Closing Hymn',data.closing,hymnIsVisible('closing'),{extraLines:hymnExtraLines('closing'),lineAlignments:hymnLineAlignments('closing'),rightLabel:hymnRightText('closing'),id:'closing'});add('benediction','entry','Benediction',data.benediction);
 let order=[];try{const parsed=JSON.parse(data.meetingItemOrder);if(Array.isArray(parsed))order=parsed;}catch{}const byId=new Map(items.map(item=>[item.id,item])),ordered=[];for(const id of order){if(byId.has(id)){ordered.push(byId.get(id));byId.delete(id);}}for(const item of byId.values()){const index=items.indexOf(item),next=items.slice(index+1).find(candidate=>ordered.some(existing=>existing.id===candidate.id));if(next)ordered.splice(ordered.findIndex(existing=>existing.id===next.id),0,item);else ordered.push(item);}for(const item of ordered)item.alignment=entryAlignment(item.id);return includeHidden?ordered:ordered.filter(item=>item.show&&item.value.trim());
}
