function calendarBorderMonths(){
 const {from}=calendarWindow(),months=new Map();for(let i=0;i<35;i++){const date=new Date(from);date.setDate(date.getDate()+i);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');if(!months.has(key))months.set(key,{key,label:date.toLocaleDateString('en-US',{month:'long',year:'numeric'}),count:0});months.get(key).count++;}
 const list=[...months.values()],main=list.reduce((best,m)=>m.count>best.count?m:best,list[0]);return list.filter(m=>m.key!==main.key);
}
