function calendarMonthLabelsEditor(){const settings=calendarMonthLabelSettings(),appearance=textAppearance(),defaultColor=appearance.calendar?.color||appearance.global?.color||'#141414';return `<details><summary style="padding:12px 0;font-weight:600;cursor:pointer">Month labels on the 1st</summary><p class="note">Edit the month name inside the first-day box. This does not change the calendar heading above the grid.</p><label class="field">Show month labels<select id="showCalendarMonthLabels"><option value="yes" ${settings.show!==false?'selected':''}>Show</option><option value="no" ${settings.show===false?'selected':''}>Hide all</option></select></label>${calendarMonthLabelDates().map(month=>{const label=settings.labels?.[month.key]||{};return `<details><summary style="padding:12px 0;font-weight:600">${esc(month.label)} · ${esc(month.date)}</summary><label class="field">This month's label<select data-month-label="${month.key}" data-month-label-part="show"><option value="yes" ${label.show!==false?'selected':''}>Show</option><option value="no" ${label.show===false?'selected':''}>Hide</option></select></label><label class="field">Label wording<input data-month-label="${month.key}" data-month-label-part="text" value="${esc(label.text??month.name)}" maxlength="120"></label><button type="button" class="secondary" data-month-label-auto="${month.key}">Restore automatic month name</button><label class="field">Label size<select data-month-label="${month.key}" data-month-label-part="size"><option value="">Use calendar formatting</option>${[6,7,8,9,10,12,14,16].map(size=>`<option value="${size}" ${Number(label.size)===size?'selected':''}>${size} pt</option>`).join('')}</select></label><label style="display:flex;gap:8px;align-items:center;margin:12px 0"><input type="checkbox" style="width:auto;margin:0" data-month-label="${month.key}" data-month-label-part="inheritColor" ${!label.color?'checked':''}>Use calendar font color</label><label class="field">Label color<input type="color" data-month-label="${month.key}" data-month-label-part="color" value="${/^#[0-9a-f]{6}$/i.test(label.color||'')?label.color:defaultColor}" ${!label.color?'disabled':''}></label></details>`;}).join('')||'<p class="note">No first-of-month dates are in this five-week view.</p>'}</details>`;}
function bindCalendarMonthLabels(){const root=$('#editor'),master=$('#showCalendarMonthLabels');if(master)master.onchange=()=>{const config=calendarMonthLabelSettings();config.show=master.value==='yes';data.calendarMonthLabels=JSON.stringify(config);save();};root.querySelectorAll('[data-month-label]').forEach(input=>input.oninput=()=>{const config=calendarMonthLabelSettings(),month=input.dataset.monthLabel,part=input.dataset.monthLabelPart,label={...config.labels?.[month]};if(part==='inheritColor'){const picker=root.querySelector('[data-month-label="'+month+'"][data-month-label-part="color"]');if(input.checked)delete label.color;else label.color=picker.value;if(picker)picker.disabled=input.checked;}else label[part]=part==='show'?input.value==='yes':input.value;config.labels={...config.labels,[month]:label};data.calendarMonthLabels=JSON.stringify(config);save();});root.querySelectorAll('[data-month-label-auto]').forEach(button=>button.onclick=()=>{const config=calendarMonthLabelSettings(),month=button.dataset.monthLabelAuto,label={...config.labels?.[month]};delete label.text;config.labels={...config.labels,[month]:label};data.calendarMonthLabels=JSON.stringify(config);save();edit();});}
function monthBorderSettings(){
 const colors=data.monthBorderColors||{},fallback=/^#[0-9a-f]{6}$/i.test(data.monthBorderColor||'')?data.monthBorderColor:'#b85432';
 return `<details style="border:1px solid #d5dacf;border-radius:5px;padding:0 12px;margin:12px 0"><summary style="padding:14px 0;font-weight:600;cursor:pointer">Calendar appearance</summary><label class="field">Month border:<select id="monthBorderMode"><option value="off" ${data.monthBorderMode==='off'?'selected':''}>Off</option><option value="black" ${data.monthBorderMode==='black'?'selected':''}>Bold black</option><option value="color" ${data.monthBorderMode==='color'?'selected':''}>Choose colors by month</option></select></label><div id="monthBorderColorField" ${data.monthBorderMode==='color'?'':'hidden'}>${calendarBorderMonths().map((month,i)=>`<label class="field">${month.label} border color:<input type="color" data-month-border="${month.key}" value="${/^#[0-9a-f]{6}$/i.test(colors[month.key]||'')?colors[month.key]:i?'#416d91':fallback}"></label>`).join('')}</div><p class="note">Outlines only the smaller month sections. The month with the most dates stays unboxed. Choose a separate color for each outlined month, or use bold black.</p>${calendarMonthLabelsEditor()}</details>`;
}
function calendarTextFields(event,index,source){return `<fieldset style="border:0;padding:0;margin:12px 0"><legend>Show text with the calendar icon?</legend>${[['yes','Show time'],['no','Icon only']].map(([value,label])=>`<label style="display:inline-flex;align-items:center;gap:7px;margin:10px 12px 0 0"><input style="width:auto;margin:0" type="radio" name="calendar-text-${source}-${index}" data-${source}="${index}" data-${source}-part="calendarText" value="${value}" ${(event.calendarText||'yes')===value?'checked':''}>${label}</label>`).join('')}</fieldset>`;}
function digitalHymns(){
 const settings=hymnLinkOptions(),make=(label,hymn,config={})=>{
  let url='';if(String(config.url||'').trim()){try{const parsed=new URL(config.url);if(parsed.protocol!=='https:')throw Error();url=parsed.href;}catch{throw Error('Use a full https:// URL for the '+label+' digital hymn link.');}}
  else if(hymn.name.trim()){
    const slug=hymn.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
    const type=config.type&&config.type!=='auto'?config.type:Number(hymn.number)>=1000?'home':'classic',base=type==='home'?'study/music/hymns-for-home-and-church/':type==='primary'?'media/music/songs/':'study/manual/hymns/';
    if(slug)url='https://www.churchofjesuschrist.org/'+base+slug+'?lang=eng';
  }
  return {label,name:hymn.name,number:hymn.number,url,rightLabel:config.rightLabel??'Hymn',extraLines:config.extraLines||[],lineAlignments:config.lineAlignments||[],alignment:entryAlignment(config.id),id:config.id};
 };
 const list=[];for(const [key,label] of [['opening','Opening Hymn'],['sacrament','Sacrament Hymn']])if(hymnIsVisible(key)&&String(data[key]||'').trim())list.push(make(label,splitHymn(data[key]),{...settings[key],extraLines:hymnExtraLines(key),lineAlignments:hymnLineAlignments(key),rightLabel:hymnRightText(key),id:key}));
 const options=readProgramOptions(),speakerCount=options.showSpeakers?options.speakers.filter(s=>s.show&&s.name.trim()).length:0;
 const extra=readExtraHymns().map((h,i)=>({...h,index:i})).filter(h=>h.show&&(h.number||h.name)).sort((a,b)=>Math.min(a.after,speakerCount)-Math.min(b.after,speakerCount)||a.index-b.index);
 for(const hymn of extra)list.push(make(hymn.label,hymn,{type:hymn.linkType,url:hymn.url,extraLines:hymn.extraLines||[],lineAlignments:hymn.lineAlignments||[],rightLabel:hymnRightText(hymn),id:'hymn-'+hymn.id}));
 if(hymnIsVisible('closing')&&String(data.closing||'').trim())list.push(make('Closing Hymn',splitHymn(data.closing),{...settings.closing,extraLines:hymnExtraLines('closing'),lineAlignments:hymnLineAlignments('closing'),rightLabel:hymnRightText('closing'),id:'closing'}));if(data.meetingItemOrder){const order=meetingSequence().map(item=>item.id);list.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));}return list;
}
function digitalProgramFormat(){return ['letter','legal'].includes(data.digitalProgramFormat)?data.digitalProgramFormat:(data.paperSize==='letter'?'letter':'legal');}
function digitalDocument(images,info){
 const sections=[['cover','Cover'],['program','Meeting program'],['announcements','Announcements'],...(info.format==='letter'?[]:[['calendar','Calendar']]),['information','Ward / branch information']];
 const safeAlign=(value,fallback='center')=>['left','center','right'].includes(value)?value:fallback;
 const hymnCaption=h=>esc(h.label)+': '+esc(h.number?((h.rightLabel?h.rightLabel+' ':'')+h.number+' · '):'')+esc(h.name)+(h.extraLines||[]).map((line,i)=>line.trim()?'<small style="display:block;font-weight:400;text-align:'+safeAlign(h.lineAlignments?.[i],safeAlign(h.alignment))+'">'+esc(line)+'</small>':'').join('');
 const hymns=info.hymns.map(h=>h.url?`<a href="${esc(h.url)}" style="text-align:${safeAlign(h.alignment)}" target="_blank" rel="noopener noreferrer">${hymnCaption(h)}</a>`:`<span style="text-align:${safeAlign(h.alignment)}">${hymnCaption(h)}</span>`).join('');
 const content=sections.map(([id,label],i)=>{if(!/^data:image\/png;base64,/.test(images[i]||''))throw Error('Could not prepare the digital '+label+'.');return `<section id="${id}" aria-label="${label}">${id==='program'&&hymns?'<nav class="song-links" aria-label="Hymns">'+hymns+'</nav>':''}<img src="${images[i]}" alt="${esc(label+' — '+info.unit)}" ${i?'loading="lazy"':''}></section>`;}).join('');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(info.unit)} Program · ${esc(info.date)}</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f5f0;color:#253b34;font:16px system-ui,Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:12px}header{text-align:center;padding:18px 8px}h1{font:clamp(23px,5vw,36px) Georgia,serif;line-height:1.2;margin:0 0 8px}header p{margin:6px 0}.draft{color:#865317;font-weight:700}.jump,.song-links{display:grid;gap:10px;margin:12px 0 20px}.jump{grid-template-columns:repeat(2,minmax(0,1fr))}a,nav span{display:block;padding:14px;text-align:center;border:1px solid #c6d1c7;border-radius:9px;text-decoration:none;color:#213e32;font-weight:600;background:#fff}a:hover{background:#eaf0e8}a:focus-visible{outline:3px solid #315b4b;outline-offset:3px}img{width:100%;height:auto;display:block;margin:16px 0 26px;border-radius:8px;background:white}section{scroll-margin-top:12px}footer{text-align:center;padding:15px 0 30px;font-size:14px;color:#56675c}@media(min-width:650px){.jump{grid-template-columns:repeat(4,minmax(0,1fr))}}@media print{.jump{display:none}body{background:white}}</style></head><body><main class="wrap"><header><h1>${esc(info.unit)}</h1><p>${esc(info.date)}</p>${info.published?'':'<p class="draft">Draft preview — not published</p>'}</header><nav class="jump" aria-label="Program sections"><a href="#program">Program & hymns</a><a href="#announcements">Announcements</a>${info.format==='letter'?'':'<a href="#calendar">Calendar</a>'}<a href="#information">Information</a></nav>${content}<footer>${esc(info.unit)} · ${esc(info.date)}</footer></main></body></html>`;
}
function digitalHymnTests(){try{const hymns=digitalHymns();return hymns.length?hymns.map(h=>`<p>${esc(h.label)}: ${esc(h.name||h.number)} ${h.url?`<a href="${esc(h.url)}" target="_blank" rel="noopener noreferrer">Test link ↗</a>`:'— enter a hymn name or custom link'}</p>`).join(''):'<p class="note">Show a hymn and enter its name to create a clickable link.</p>';}catch(error){return `<p role="alert">${esc(error.message)}</p>`;}}
function digitalEditor(){return `<h3>Digital Program</h3><label>Digital program format<select data-key="digitalProgramFormat"><option value="" ${!data.digitalProgramFormat?'selected':''}>Match printed paper size</option><option value="letter" ${data.digitalProgramFormat==='letter'?'selected':''}>Standard — no full calendar</option><option value="legal" ${data.digitalProgramFormat==='legal'?'selected':''}>Legal — include calendar</option></select></label><p class="note">Standard displays the cover, meeting program, announcements, and ward/branch information. Legal also includes the full calendar. This choice only changes the digital program.</p><p id="digitalTabSlot">${digitalProgramSiteLink()}</p>${meetingField(['digitalProgramUrl','Online program URL','url'])}<p class="note">The online link currently opens your existing program site. Editor changes appear in the preview here; publish and upload the digital program to update that site.</p><p class="note">Preview the selected format as a mobile-friendly page with clickable hymn links.</p><details><summary style="padding:14px 0;font-weight:600;cursor:pointer">Clickable hymns</summary><p class="note">These are the same hymns used in Meeting. Edit the number, name, collection, or custom link here. Hidden hymns are omitted from the digital program. A custom https:// link overrides the suggested link.</p>${hymnFields('opening','Opening Hymn')}${hymnFields('sacrament','Sacrament Hymn')}${extraHymnFields()}${hymnFields('closing','Closing Hymn')}<h4>Test hymn links</h4><p class="note">Open each link to check the correct song before publishing. Suggested links use the hymn name; paste the exact song URL if needed.</p><div id="digitalHymnTests">${digitalHymnTests()}</div></details><button type="button" id="downloadDigital" ${data.publicationStatus==='published'?'':'hidden'}>Download digital program</button><p class="note">Publish this week’s bulletin to enable the download. Upload the resulting HTML file to your public program site; it contains its images and does not require separate image files.</p>`;}
function bindDigital(){const button=$('#downloadDigital');if(button)button.onclick=async()=>{if(data.publicationStatus!=='published'){status('Publish this week’s bulletin first.');return;}button.disabled=true;try{if(window.BulletinAccess)await window.BulletinAccess.ensureBulletin(data.date,data.programStyle||'sacrament');if(!window.createDigitalExport)throw Error('The preview is still starting. Try again in a moment.');const html=await window.createDigitalExport();download(new Blob([html],{type:'text/html;charset=utf-8'}),'digital-program.html');status('Digital program downloaded. Upload the HTML file to your public program site.');}catch(error){status(error.message);}finally{button.disabled=false;}};}
function calendarEditor(){
 return `<details style="border:1px solid #d5dacf;border-radius:5px;padding:0 12px;margin:12px 0"><summary style="padding:14px 0;font-weight:600;cursor:pointer">Other calendar items</summary><p class="note">Add holidays, reminders, or events without announcements. No icon means text only. Dates beyond the five-week calendar appear as text in Future events.</p>${readCalendar().map((event,i)=>`<details data-calendar-panel="${i}" ${calendarExpanded.has(i)?'open':''} style="border:1px solid #d5dacf;border-radius:4px;padding:10px;margin:12px 0"><summary data-calendar-heading="${i}" style="font-weight:600;cursor:pointer">${esc(event.title||'Calendar item '+(i+1))}</summary>${[true,false].map(show=>`<label style="display:inline-flex;gap:5px;align-items:center;margin:8px 14px 0 0;font-size:12px"><input type="radio" style="width:auto;margin:0" name="calendar-show-${i}" data-calendar="${i}" data-calendar-part="show" value="${show}" ${(event.show!==false)===show?'checked':''}>${show?'Show':'Hide'}</label>`).join('')}<label class="field">Event name:<input data-calendar="${i}" data-calendar-part="title" value="${esc(event.title)}"></label><label class="field">Date:<input type="date" data-calendar="${i}" data-calendar-part="date" value="${esc(event.date||'')}"></label><label class="field">Time (optional):<input type="time" data-calendar="${i}" data-calendar-part="time" value="${esc(event.time||'')}"></label>${repeatFields(event,'calendar',i)}${calendarTextFields(event,i,'calendar')}<label class="field">Icon:<select data-calendar="${i}" data-calendar-part="icon">${[...newsIcons,['10','Thanksgiving'],['11','Veterans Day'],['13','Election Day'],['1','Sacrament meeting'],['family-evening','Family home evening']].map(([value,label])=>`<option value="${value}" ${value==='upload'?'style="font-weight:700"':''} ${event.icon===value?'selected':''}>${label}</option>`).join('')}</select></label><div data-calendar-upload="${i}" ${event.icon==='upload'?'':'hidden'}><label class="field">Upload image:<input type="file" accept="image/jpeg,image/png" data-calendar-image="${i}"></label><p class="note">Use a square PNG or JPG, at least 300 × 300 pixels. Simple artwork prints best.</p>${event.image?`<img src="${esc(event.image)}" alt="Calendar image" style="max-width:100%;max-height:100px">`:''}</div><button type="button" class="secondary" data-calendar-remove="${i}">Remove calendar item</button></details>`).join('')}<button type="button" class="secondary" id="addCalendarItem">Add calendar item</button><p></p></details>`;
}
function bindCalendar(){
 const borderMode=$('#monthBorderMode');if(borderMode)borderMode.onchange=()=>{data.monthBorderMode=borderMode.value;const colorField=$('#monthBorderColorField');if(colorField)colorField.hidden=borderMode.value!=='color';save();};
 $('#editor').querySelectorAll('[data-month-border]').forEach(input=>input.oninput=()=>{data.monthBorderColors={...(data.monthBorderColors||{}),[input.dataset.monthBorder]:input.value};save();});
 const root=$('#editor');
 root.querySelectorAll('[data-calendar-panel]').forEach(panel=>panel.ontoggle=()=>{if(panel.open)calendarExpanded.add(+panel.dataset.calendarPanel);else calendarExpanded.delete(+panel.dataset.calendarPanel);});
 root.querySelectorAll('[data-calendar]').forEach(e=>e.oninput=()=>{const list=readCalendar(),i=+e.dataset.calendar,part=e.dataset.calendarPart;list[i][part]=part==='show'?e.value==='true':e.value;if(part==='title'){const heading=root.querySelector('[data-calendar-heading="'+i+'"]');if(heading)heading.textContent=e.value||'Calendar item '+(i+1);}if(part==='icon'){const upload=root.querySelector('[data-calendar-upload="'+i+'"]');if(upload)upload.hidden=e.value!=='upload';}saveCalendar(list);});
 const add=$('#addCalendarItem');if(add)add.onclick=()=>{const list=readCalendar();list.push({title:'',date:'',time:'',show:true,icon:'',image:''});saveCalendar(list);edit();};
 root.querySelectorAll('[data-calendar-remove]').forEach(e=>e.onclick=()=>{const list=readCalendar();list.splice(+e.dataset.calendarRemove,1);calendarExpanded.clear();saveCalendar(list);edit();});
 root.querySelectorAll('[data-calendar-image]').forEach(e=>e.onchange=async()=>{const file=e.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)){status('Choose a JPEG or PNG image.');return;}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const list=readCalendar();list[+e.dataset.calendarImage].image=canvas.toDataURL('image/png');bitmap.close();saveCalendar(list);edit();}catch{status('Could not open this image.');}});
}
function calendarDayLayouts(){try{return JSON.parse(data.calendarDayLayouts)||{}}catch{return {}}}
function ensureCalendarItemIds(){let changed=false;const identify=list=>list.map(item=>{if(item.calendarId)return item;changed=true;return {...item,calendarId:globalThis.crypto?.randomUUID?.()||'item-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)};});const news=identify(readNews()),calendar=identify(readCalendar());if(changed){data.newsOptions=JSON.stringify(news);data.calendarOptions=JSON.stringify(calendar);}}
function calendarDayEditor(){ensureCalendarItemIds();const {from,through}=calendarWindow(),days=new Map();for(const event of events().filter(e=>e.art!=null&&e.date>=dateKey(from)&&e.date<=dateKey(through))){if(!days.has(event.date))days.set(event.date,[]);days.get(event.date).push(event);}return `<details><summary style="padding:14px 0;font-weight:600;cursor:pointer">Calendar day icon order &amp; size</summary><p class="note">Expand a date, then drag the grips to set the top-to-bottom order in that box. You can also use the Up/Down arrow keys. Larger gives an icon more space. Changes apply to that date only.</p>${[...days].map(([date,items])=>`<details><summary style="padding:12px 0;font-weight:600;cursor:pointer">${esc(new Date(date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}))} · ${items.length} icons</summary>${items.map((event,i)=>`<div data-order-item="day:${date}" data-order-index="${i}" style="border-top:1px solid #d5dacf;padding:10px 0">${orderHandle('day:'+date,i,event.title)}<strong>${esc(event.title)}</strong><label class="field">Icon size:<select data-day-icon-date="${date}" data-day-icon-id="${esc(event.calendarKey)}">${[['small','Smaller'],['normal','Normal'],['large','Larger']].map(([value,label])=>`<option value="${value}" ${(event.iconSize||'normal')===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`).join('')}</details>`).join('')||'<p class="note">Add an icon to a calendar date to arrange it here.</p>'}</details>`;}
function reorderCalendarDay(date,from,to){const items=events().filter(e=>e.date===date&&e.art!=null);if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=items.length||to>=items.length||from===to)return false;const order=items.map(e=>e.calendarKey);order.splice(to,0,order.splice(from,1)[0]);const layouts=calendarDayLayouts();layouts[date]={...layouts[date],order};data.calendarDayLayouts=JSON.stringify(layouts);save();edit();status('Calendar icon order updated.');return true;}
function bindCalendarDayLayout(){$('#editor').querySelectorAll('[data-day-icon-date]').forEach(input=>input.onchange=()=>{const layouts=calendarDayLayouts(),date=input.dataset.dayIconDate,day=layouts[date]||{};layouts[date]={...day,sizes:{...day.sizes,[input.dataset.dayIconId]:input.value}};data.calendarDayLayouts=JSON.stringify(layouts);save();});}
function calendarTime(value){if(!/^\d{2}:\d{2}$/.test(value||''))return '';const [h,m]=value.split(':').map(Number);return (h%12||12)+(m?':'+String(m).padStart(2,'0'):'')+' '+(h>=12?'pm':'am');}
function calendarArt(event){
 if(event.icon==='upload')return /^data:image\/(png|jpeg);base64,/.test(event.image||'')?event.image:null;
 if(event.icon&&event.icon!=='auto')return event.icon;
 if(event.icon!=='auto')return null;
 const match=event.title.match(/sacrament|youth|primary program|christmas|thanksgiving|veterans|election|choir|family home evening|primary activities|relief society|lunch/i);
 return match?({sacrament:'1',youth:'2','primary program':'8',christmas:'0',thanksgiving:'10',veterans:'11',election:'13',choir:'choir','family home evening':'family-evening','primary activities':'primary-activities','relief society':'20',lunch:'lunch'}[match[0].toLowerCase()]):null;
}
let bulkEditing=false,bulkSelection=new Set(),bulkUndo=null;
const expandedEditorSections=new Set();
function bulkToolbar(){return `<div class="bulk-toolbar">${bulkUndo?'<button type="button" class="secondary" id="bulkUndo">Undo last bulk deletion</button>':''}<button type="button" class="bulk-edit-pill" id="bulkStart" title="Select multiple items to delete">Bulk edit</button></div>`;}
function bulkEditor(){
 const lists=[['news','Announcements',readNews()],['calendar','Other calendar items',readCalendar()]];
 return `<h3>Bulk edit</h3><p class="note">Select the items you want to delete. Deleting an announcement also removes its linked calendar dates. A repeating calendar item is selected as one item.</p><div style="display:flex;flex-wrap:wrap;gap:8px"><button type="button" class="secondary" id="bulkAll">Select all</button><button type="button" class="secondary" id="bulkNone">Clear selection</button><button type="button" class="secondary" id="bulkCancel">Cancel</button></div>${lists.map(([kind,title,items])=>`<h4>${title}</h4>${items.length?items.map((item,index)=>`<label style="display:flex;gap:10px;align-items:flex-start;border-bottom:1px solid #d5dacf;padding:12px 0"><input style="width:auto;margin:2px 0 0" type="checkbox" data-bulk-item="${kind}:${index}" ${bulkSelection.has(kind+':'+index)?'checked':''}><span>${esc(item.title||title+' '+(index+1))}<small style="display:block;color:#536355">${item.recurring?'Recurring · ':''}${item.show===false?'Hidden':'Shown'}${item.date?' · '+esc(item.date):''}</small></span></label>`).join(''):'<p class="note">No items.</p>'}`).join('')}<p id="bulkCount" class="note">${bulkSelection.size} selected</p><button type="button" id="bulkDelete" ${bulkSelection.size?'':'disabled'}>Delete selected (${bulkSelection.size})</button><p></p>`;
}
function deleteBulkItems(){
 if(!bulkSelection.size)return;
 bulkUndo={newsOptions:data.newsOptions,announcements:data.announcements,calendarOptions:data.calendarOptions};
 const news=readNews().filter((item,i)=>!bulkSelection.has('news:'+i)),calendar=readCalendar().filter((item,i)=>!bulkSelection.has('calendar:'+i)),count=bulkSelection.size;
 saveNews(news);saveCalendar(calendar);bulkSelection.clear();bulkEditing=false;expandedAnnouncements.clear();calendarExpanded.clear();expandedEditorSections.clear();edit();status(count+' items deleted. Use Undo last bulk deletion to restore them.');
}
function bindBulkEdit(){
 const start=$('#bulkStart');if(start)start.onclick=()=>{bulkEditing=true;bulkSelection.clear();edit();};
 const cancel=$('#bulkCancel');if(cancel)cancel.onclick=()=>{bulkEditing=false;bulkSelection.clear();edit();};
 const undo=$('#bulkUndo');if(undo)undo.onclick=()=>{if(!bulkUndo)return;Object.assign(data,bulkUndo);bulkUndo=null;save();edit();status('Bulk deletion undone.');};
 const update=()=>{const count=$('#bulkCount'),button=$('#bulkDelete');if(count)count.textContent=bulkSelection.size+' selected';if(button){button.disabled=!bulkSelection.size;button.textContent='Delete selected ('+bulkSelection.size+')';}};
 $('#editor').querySelectorAll('[data-bulk-item]').forEach(input=>input.onchange=()=>{if(input.checked)bulkSelection.add(input.dataset.bulkItem);else bulkSelection.delete(input.dataset.bulkItem);update();});
 const all=$('#bulkAll');if(all)all.onclick=()=>{$('#editor').querySelectorAll('[data-bulk-item]').forEach(input=>{input.checked=true;bulkSelection.add(input.dataset.bulkItem);});update();};
 const none=$('#bulkNone');if(none)none.onclick=()=>{bulkSelection.clear();$('#editor').querySelectorAll('[data-bulk-item]').forEach(input=>input.checked=false);update();};
 const remove=$('#bulkDelete');if(remove)remove.onclick=deleteBulkItems;
}
function bindCollapsedSections(){
 $('#editor').querySelectorAll('details').forEach((section,index)=>{const key=tab+':'+index;section.open=expandedEditorSections.has(key);section.addEventListener('toggle',()=>{if(section.open)expandedEditorSections.add(key);else expandedEditorSections.delete(key);});});
}
let orderDrag=null;
function orderHandle(kind,index,title){return `<button type="button" class="order-handle" draggable="true" data-order-handle="${kind}" data-order-index="${index}" aria-label="Reorder ${esc(title)} ${index+1}" title="Drag to reorder, or use Up/Down arrow keys">⠿</button>`;}
function reorderEntries(kind,from,to){
 if(kind==='meeting'){const items=meetingSequence(true);if(from===to||from<0||to<0||from>=items.length||to>=items.length)return false;items.splice(to,0,items.splice(from,1)[0]);data.meetingItemOrder=JSON.stringify(items.map(item=>item.id));save();edit();const panel=$('#editor').querySelector('[data-meeting-order]');if(panel)panel.open=true;status('Program order updated.');return true;}
 if(kind.startsWith('day:'))return reorderCalendarDay(kind.slice(4),from,to);
 const list=kind==='announcements'?readNews():kind==='leadership'?readWard().leadership:null;
 if(!list||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=list.length||to>=list.length||from===to)return false;
 list.splice(to,0,list.splice(from,1)[0]);
 if(kind==='announcements'){
  const map=index=>index===from?to:from<to&&index>from&&index<=to?index-1:from>to&&index>=to&&index<from?index+1:index;
  const open=[...expandedAnnouncements];expandedAnnouncements.clear();for(const index of open)expandedAnnouncements.add(map(index));saveNews(list);
 }else{const w=readWard();w.leadership=list;saveWard(w);}
 edit();status((kind==='leadership'?'Leadership':'Announcement')+' order updated.');return true;
}
function bindOrdering(){
 const root=$('#editor');
 root.querySelectorAll('[data-meeting-position]').forEach(select=>select.onchange=()=>reorderEntries('meeting',+select.dataset.meetingPosition,+select.value));
 const clear=()=>root.querySelectorAll('[data-order-item]').forEach(row=>row.classList.remove('order-over','order-dragging'));
 root.querySelectorAll('[data-order-handle]').forEach(handle=>{
  handle.ondragstart=event=>{orderDrag={kind:handle.dataset.orderHandle,index:+handle.dataset.orderIndex};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',orderDrag.kind+':'+orderDrag.index);const row=handle.closest('[data-order-item]');if(row)row.classList.add('order-dragging');};
  handle.ondragend=()=>{orderDrag=null;clear();};
  handle.onkeydown=event=>{if(event.key!=='ArrowUp'&&event.key!=='ArrowDown')return;event.preventDefault();const kind=handle.dataset.orderHandle,index=+handle.dataset.orderIndex,target=index+(event.key==='ArrowUp'?-1:1);if(reorderEntries(kind,index,target)){const moved=$('#editor').querySelector('[data-order-handle="'+kind+'"][data-order-index="'+target+'"]');if(moved)moved.focus();}};
 });
 root.querySelectorAll('[data-order-item]').forEach(row=>{
  row.ondragover=event=>{if(!orderDrag||orderDrag.kind!==row.dataset.orderItem)return;event.preventDefault();event.dataTransfer.dropEffect='move';clear();row.classList.add('order-over');};
  row.ondragleave=event=>{if(!row.contains(event.relatedTarget))row.classList.remove('order-over');};
  row.ondrop=event=>{if(!orderDrag||orderDrag.kind!==row.dataset.orderItem)return;event.preventDefault();const from=orderDrag.index,kind=orderDrag.kind;orderDrag=null;clear();reorderEntries(kind,from,+row.dataset.orderIndex);};
 });
}
function coverEditor(){
 const source=data.coverImageSource||(data.cover===defaults.cover?'default':'upload');
 return `<p class="note">The Church title stays fixed. Ward and stake names are shared with the Meeting tab.</p><details><summary style="font-weight:600;cursor:pointer;padding:14px 0">Ward and stake</summary>${meetingField(['ward','Ward / branch name (optional)'])}${meetingField(['stake','Stake name'])}</details><details><summary style="font-weight:600;cursor:pointer;padding:14px 0">Cover image</summary><fieldset style="border:0;padding:0"><legend>Image source</legend>${[['default','Use default image'],['upload','Upload an image']].map(([value,label])=>`<label style="display:flex;align-items:center;gap:8px;margin:12px 0"><input style="width:auto;margin:0" type="radio" name="cover-source" data-cover-source value="${value}" ${source===value?'checked':''}>${label}</label>`).join('')}</fieldset><div id="coverUploadFields" ${source==='upload'?'':'hidden'}><label class="field">Upload cover image<input type="file" id="cover" accept="image/jpeg,image/png"></label><p class="note">PNG or JPG. A portrait image works best; it is scaled to fit without cropping.</p></div><p class="note">The current default is your existing cover image. More default choices can be added when you provide them.</p></details><details><summary style="font-weight:600;cursor:pointer;padding:14px 0">Quote (optional)</summary>${meetingField(['coverQuote','Quote or message below the image','textarea'])}<p class="note">Leave blank to omit it. Keep the message short so it fits clearly.</p></details><details><summary style="font-weight:600;cursor:pointer;padding:14px 0">QR code</summary><fieldset style="border:0;padding:0"><legend>Add QR code?</legend>${[['yes','Yes'],['no','No']].map(([value,label])=>`<label style="display:inline-flex;align-items:center;gap:8px;margin:12px 16px 0 0"><input style="width:auto;margin:0" type="radio" name="cover-qr" data-cover-qr value="${value}" ${data.coverShowQr===value?'checked':''}>${label}</label>`).join('')}</fieldset><div id="coverQrFields" ${data.coverShowQr==='yes'?'':'hidden'}><label class="field">Upload QR code image<input type="file" id="coverQrUpload" accept="image/jpeg,image/png"></label><p class="note">Upload your QR code as a square PNG or JPG, with its white border intact.</p>${data.coverQr?`<img src="${esc(data.coverQr)}" alt="QR code" style="max-width:110px;max-height:110px"><button type="button" id="removeCoverQr" class="secondary">Remove QR image</button>`:'<p class="note">Choose a QR image to include it on the cover.</p>'}</div></details>`;
}
async function readCoverImage(file,maxSize,qr=false){
 if(!['image/jpeg','image/png'].includes(file.type))throw Error('Choose a JPEG or PNG image.');
 const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,maxSize/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return qr?canvas.toDataURL('image/png'):canvas.toDataURL('image/jpeg',.9);
}
function bindCover(){
 if(tab!=='Cover')return;
 $('#editor').querySelectorAll('[data-cover-source]').forEach(input=>input.onchange=()=>{
  if(input.value==='default'){if(data.cover!==defaults.cover)data.coverUpload=data.cover;data.cover=defaults.cover;}
  else if(data.coverUpload)data.cover=data.coverUpload;
  data.coverImageSource=input.value;const fields=$('#coverUploadFields');if(fields)fields.hidden=input.value!=='upload';save();
 });
 const upload=$('#cover');if(upload)upload.onchange=async()=>{const file=upload.files[0];if(!file)return;try{data.coverUpload=await readCoverImage(file,1400);data.cover=data.coverUpload;data.coverImageSource='upload';save();status('Cover image updated.');}catch(error){status(error.message);}};
 $('#editor').querySelectorAll('[data-cover-qr]').forEach(input=>input.onchange=()=>{data.coverShowQr=input.value;$('#coverQrFields').hidden=input.value!=='yes';save();});
 const qr=$('#coverQrUpload');if(qr)qr.onchange=async()=>{const file=qr.files[0];if(!file)return;try{data.coverQr=await readCoverImage(file,1000,true);save();edit();status('QR image updated.');}catch(error){status(error.message);}};
 const remove=$('#removeCoverQr');if(remove)remove.onclick=()=>{data.coverQr='';save();edit();};
}
