 for(const option of host.querySelector('select').options){option.disabled=!!option.value&&Array.isArray(window.BulletinAccess?.allowedStyles)&&!window.BulletinAccess.allowedStyles.includes(option.value);}
 const label=$('#selectedProgramStyle');if(label)label.textContent=(programStyleChoices.find(style=>style[0]===data.programStyle)||programStyleChoices[0])[1];
 const size=$('#paperSize'),color=$('#printColor');
