function render(){updateProgramStyleControls();updateTextAppearanceControls();updateDigitalSiteLink();updateWeekHeader();updatePrintSettings();updateProgramStyleControls();$('#edition').textContent=dateText();if(window.renderPrintPreview)window.renderPrintPreview();}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}
$('#saveDraft').onclick=()=>download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`bulletin-${data.date}.json`);$('#importDraft').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!d||typeof d!=='object'||Array.isArray(d))throw Error();const clean={};for(const k of Object.keys(defaults)){if(typeof d[k]==='string')clean[k]=d[k]}if(clean.date&&!/^\d{4}-\d{2}-\d{2}$/.test(clean.date))throw Error();for(const key of ['coverQr','coverUpload'])if(clean[key]&&!/^data:image\/(jpeg|png);base64,/.test(clean[key]))throw Error();if(clean.cover&&!/^(data:image\/(jpeg|png);base64,|reference-1-1.jpg$)/.test(clean.cover))throw Error();data={...defaults,...clean,programSetupStep:clean.programSetupStep??'3'};syncProgram(readProgramOptions());save();edit();status('Draft imported.')}catch{status('Could not import this draft. Select a Bulletin Studio JSON file.')}};$('#next').onclick=()=>{const date=meetingDate();date.setDate(date.getDate()+7);switchWeek(dateKey(date));};$('#side').onchange=render;
const paperSizeControl=$('#paperSize');if(paperSizeControl)paperSizeControl.onchange=()=>{if(!paperSizeControl.value)return;programSetupStep=Math.max(2,programSetupStep);data.programSetupStep=String(programSetupStep);data.paperSize=paperSizeControl.value;$('#side').value=tab==='Digital Program'?'digital':data.paperSize==='letter'?(tab==='Ward / Branch'||tab==='Cover'?'0':'1'):(tab==='News / Calendar'?'0':'1');save();};
const printColorControl=$('#printColor');if(printColorControl)printColorControl.onchange=()=>{if(!printColorControl.value)return;programSetupStep=3;data.programSetupStep='3';data.printColor=printColorControl.value;save();};
const weekControl=$('#weekOf');if(weekControl)weekControl.onchange=()=>switchWeek(weekControl.value);
const publishControl=$('#publishBulletin');if(publishControl)publishControl.onclick=async()=>{publishControl.disabled=true;status('Checking and publishing this week’s bulletin…');const snapshot=JSON.stringify(data),captured=JSON.parse(snapshot);if(replacementPublication&&captured.date!==replacementPublication.week){status('Return to week '+replacementPublication.week+' to publish this replacement, or cancel replacement mode.');publishControl.disabled=false;return;}try{if(window.BulletinAccess)await window.BulletinAccess.ensureBulletin(captured.date,captured.programStyle||'sacrament');if(!captured.date||Number.isNaN(meetingDate().getTime()))throw Error('Choose a valid Week of date.');const result=await makePdf();if(snapshot!==JSON.stringify(data))throw Error('The draft changed during the check. Review it and publish again.');if(!window.BulletinCloud?.publishBulletinPdf)throw Error('The published archive is not connected. Return to your dashboard and sign in again.');status('Saving the published PDF…');const publication=await window.BulletinCloud.publishBulletinPdf(result.bytes,{week:captured.date,unitName:captured.ward||'',paperSize:captured.paperSize||'legal',programStyle:captured.programStyle||'sacrament',printColor:captured.printColor||'color',draft:captured,replaceId:replacementPublication?.id||null});const changed=snapshot!==JSON.stringify(data);if(!changed){data.publicationStatus='published';data.publishedBulletinId=publication.id;}save(false);window.location.assign('published.html?id='+encodeURIComponent(publication.id)+(changed?'&draftChanged=1':''));}catch(error){status(/schema cache|relation .*does not exist/i.test(error.message||'')?'Published archive setup is needed. Run the Published Archive setup SQL, then try again.':error.message);}finally{publishControl.disabled=false}};
const oldExport=$('#export');if(oldExport)oldExport.onclick=async()=>{if(data.publicationStatus!=='published'){status('Publish this week’s bulletin before downloading the PDF.');return;}const btn=$('#export');btn.disabled=true;status('Preparing your print-ready PDF…');try{if(window.BulletinAccess)await window.BulletinAccess.ensureBulletin(data.date,data.programStyle||'sacrament');if(!data.date||isNaN(meetingDate()))throw Error('Choose a valid meeting date.');const r=await makePdf();download(new Blob([r.bytes],{type:'application/pdf'}),`Bulletin-${data.date}.pdf`);status(r.warnings.length?'PDF downloaded. Review smaller text in: '+[...new Set(r.warnings)].join(', '):'PDF downloaded. Print on '+(data.paperSize==='letter'?'letter':'legal')+' paper, landscape, double-sided, flip on short edge.')}catch(e){status(e.message)}finally{btn.disabled=false}};syncProgram(readProgramOptions());edit();render();



window.bulletinDraftStorageReady=initializeDraftStorage();
